CREATE SCHEMA IF NOT EXISTS app;
REVOKE ALL ON SCHEMA app FROM PUBLIC;
CREATE TABLE app.workspaces(id uuid PRIMARY KEY,owner_id uuid NOT NULL UNIQUE,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE app.tables(id uuid PRIMARY KEY,workspace_id uuid NOT NULL REFERENCES app.workspaces(id),name text NOT NULL CHECK(length(trim(name))>0),revision bigint NOT NULL DEFAULT 1,row_count int NOT NULL DEFAULT 0 CHECK(row_count BETWEEN 0 AND 5000),column_count int NOT NULL DEFAULT 0 CHECK(column_count BETWEEN 0 AND 50),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(id,workspace_id));
CREATE TABLE app.columns(id uuid PRIMARY KEY,table_id uuid NOT NULL REFERENCES app.tables(id) ON DELETE CASCADE,name text NOT NULL CHECK(length(trim(name))>0),revision bigint NOT NULL DEFAULT 1,position int NOT NULL,definition jsonb NOT NULL,UNIQUE(id,table_id));
CREATE UNIQUE INDEX column_names ON app.columns(table_id,lower(trim(name)));
CREATE TABLE app.rows(id uuid PRIMARY KEY,table_id uuid NOT NULL REFERENCES app.tables(id) ON DELETE CASCADE,sequence bigint GENERATED ALWAYS AS IDENTITY,UNIQUE(id,table_id));
CREATE TABLE app.cells(row_id uuid NOT NULL,column_id uuid NOT NULL,table_id uuid NOT NULL,value jsonb NOT NULL,version bigint NOT NULL DEFAULT 1,stale boolean NOT NULL DEFAULT false,outcome text CHECK(outcome IN ('queued','running','succeeded','reused','no_result','failed','skipped','canceled','unknown')),source_step_id uuid,PRIMARY KEY(row_id,column_id),FOREIGN KEY(row_id,table_id) REFERENCES app.rows(id,table_id) ON DELETE CASCADE,FOREIGN KEY(column_id,table_id) REFERENCES app.columns(id,table_id) ON DELETE CASCADE);
CREATE TABLE app.views(table_id uuid PRIMARY KEY REFERENCES app.tables(id) ON DELETE CASCADE,revision bigint NOT NULL DEFAULT 1,definition jsonb NOT NULL);
CREATE TABLE app.connections(id uuid PRIMARY KEY,workspace_id uuid NOT NULL REFERENCES app.workspaces(id),provider_key text NOT NULL CHECK(provider_key IN('pdl','hunter','snov','openai','tomba')),revision bigint NOT NULL DEFAULT 1,status text NOT NULL,ciphertext text NOT NULL,key_version text NOT NULL DEFAULT '1',validated_at timestamptz,validation_evidence_id uuid,UNIQUE(id,workspace_id));
CREATE TABLE app.plans(id uuid PRIMARY KEY,workspace_id uuid NOT NULL REFERENCES app.workspaces(id),table_id uuid NOT NULL,kind text NOT NULL CHECK(kind IN('import','run')),revision bigint NOT NULL DEFAULT 1,expires_at timestamptz NOT NULL,payload jsonb NOT NULL,committed_key text,committed_fingerprint text,committed_result jsonb,FOREIGN KEY(table_id,workspace_id) REFERENCES app.tables(id,workspace_id) ON DELETE CASCADE);
CREATE TABLE app.runs(id uuid PRIMARY KEY,workspace_id uuid NOT NULL REFERENCES app.workspaces(id),table_id uuid NOT NULL,parent_run_id uuid,status text NOT NULL CHECK(status IN('queued','running','cancel_requested','completed','canceled')),idempotency_key text NOT NULL,request_fingerprint text NOT NULL,snapshot jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),completed_at timestamptz,UNIQUE(workspace_id,idempotency_key),UNIQUE(id,workspace_id),UNIQUE(id,table_id),FOREIGN KEY(table_id,workspace_id) REFERENCES app.tables(id,workspace_id) ON DELETE CASCADE,FOREIGN KEY(parent_run_id,workspace_id) REFERENCES app.runs(id,workspace_id));
CREATE TABLE app.steps(id uuid PRIMARY KEY,run_id uuid NOT NULL,table_id uuid NOT NULL,row_id uuid NOT NULL,column_id uuid NOT NULL,prerequisite_ids uuid[] NOT NULL DEFAULT '{}',outcome text NOT NULL CHECK(outcome IN('queued','running','succeeded','reused','no_result','failed','skipped','canceled','unknown')),fencing bigint NOT NULL DEFAULT 0,lease_until timestamptz,result jsonb,reason text,provenance jsonb,source_step_id uuid,UNIQUE(id,run_id),FOREIGN KEY(run_id,table_id) REFERENCES app.runs(id,table_id) ON DELETE CASCADE,FOREIGN KEY(row_id,table_id) REFERENCES app.rows(id,table_id) ON DELETE CASCADE,FOREIGN KEY(column_id,table_id) REFERENCES app.columns(id,table_id) ON DELETE CASCADE);
CREATE TABLE app.reservations(row_id uuid NOT NULL,column_id uuid NOT NULL,step_id uuid NOT NULL UNIQUE REFERENCES app.steps(id) ON DELETE CASCADE,table_id uuid NOT NULL,PRIMARY KEY(row_id,column_id),FOREIGN KEY(row_id,table_id) REFERENCES app.rows(id,table_id) ON DELETE CASCADE,FOREIGN KEY(column_id,table_id) REFERENCES app.columns(id,table_id) ON DELETE CASCADE);
CREATE TABLE app.attempts(id uuid PRIMARY KEY,step_id uuid NOT NULL REFERENCES app.steps(id) ON DELETE CASCADE,connection_id uuid NOT NULL REFERENCES app.connections(id),connection_revision bigint NOT NULL,provider_key text NOT NULL,position int NOT NULL,dispatch_state text NOT NULL CHECK(dispatch_state IN('prepared','dispatch_intent','awaiting_result','resolved','unknown')),task jsonb,request_id text,deadline_at timestamptz NOT NULL,outcome text,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE app.usage_observations(id uuid PRIMARY KEY,workspace_id uuid NOT NULL REFERENCES app.workspaces(id),attribution_key uuid NOT NULL,run_id uuid REFERENCES app.runs(id) ON DELETE SET NULL,attempt_id uuid REFERENCES app.attempts(id) ON DELETE SET NULL,provider_key text NOT NULL,capability text NOT NULL,request_time timestamptz NOT NULL DEFAULT now(),observation_key text NOT NULL,source_revision bigint,semantics text NOT NULL CHECK(semantics IN('unknown','estimate','cumulative','delta')),units numeric,unit_kind text,reported_amount numeric,currency text,estimated_amount numeric,UNIQUE(workspace_id,attribution_key,observation_key));
CREATE TABLE app.consumption(id uuid PRIMARY KEY,workspace_id uuid NOT NULL REFERENCES app.workspaces(id),attribution_key uuid NOT NULL,run_id uuid REFERENCES app.runs(id) ON DELETE SET NULL,attempt_id uuid REFERENCES app.attempts(id) ON DELETE SET NULL,provider_key text NOT NULL,capability text NOT NULL,request_time timestamptz NOT NULL DEFAULT now(),unit_kind text NOT NULL DEFAULT '',currency text NOT NULL DEFAULT '',units numeric,reported_amount numeric,estimated_amount numeric,source_revision bigint,observation_key text,revision bigint NOT NULL DEFAULT 1,UNIQUE(workspace_id,attribution_key,unit_kind,currency));
CREATE INDEX runnable_steps ON app.steps(outcome,lease_until);
CREATE INDEX table_rows ON app.rows(table_id,sequence,id);
CREATE INDEX workspace_tables ON app.tables(workspace_id,updated_at DESC);
CREATE INDEX month_usage ON app.consumption(workspace_id,request_time,provider_key);
CREATE FUNCTION app.capacity_count() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF TG_TABLE_NAME='rows' THEN
  IF TG_OP='INSERT' THEN UPDATE app.tables SET row_count=row_count+1 WHERE id=NEW.table_id; RETURN NEW; ELSE UPDATE app.tables SET row_count=row_count-1 WHERE id=OLD.table_id; RETURN OLD; END IF;
 ELSE
  IF TG_OP='INSERT' THEN UPDATE app.tables SET column_count=column_count+1 WHERE id=NEW.table_id; RETURN NEW; ELSE UPDATE app.tables SET column_count=column_count-1 WHERE id=OLD.table_id; RETURN OLD; END IF;
 END IF;
END $$;
CREATE TRIGGER row_capacity BEFORE INSERT OR DELETE ON app.rows FOR EACH ROW EXECUTE FUNCTION app.capacity_count();
CREATE TRIGGER column_capacity BEFORE INSERT OR DELETE ON app.columns FOR EACH ROW EXECUTE FUNCTION app.capacity_count();
CREATE FUNCTION app.immutable_run() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.snapshot IS DISTINCT FROM OLD.snapshot OR NEW.request_fingerprint<>OLD.request_fingerprint OR NEW.idempotency_key<>OLD.idempotency_key THEN RAISE EXCEPTION 'immutable_run'; END IF; RETURN NEW; END $$;
CREATE TRIGGER immutable_snapshot BEFORE UPDATE ON app.runs FOR EACH ROW EXECUTE FUNCTION app.immutable_run();
REVOKE ALL ON ALL TABLES IN SCHEMA app FROM PUBLIC;
